import base64,hashlib,json,sys,types,unittest
raws={n:base64.b64decode(v) for n,v in {'r2_contract.py': '', 'r2_cache.py': '', 'prepare_r2.py': '', 'launch_r2.py': '', 'verify_r2.py': ''}.items()}
refs={n:base64.b64decode(v) for n,v in {'build-receipt.json': '', 'image-inspect-original.json': '', 'failed-r2-upload-source.py': '', 'prior-r2-render-refusal.json': '', 'prior-r2-du-refusal.json': '', 'actual-r2-du-command-result.json': '', 'actual-r2-plan.json': ''}.items()}
expected={'r2_contract.py': '318815e2b2cd01a9651904fe60709e1fc4659541c9e67e203d374015aa072208', 'r2_cache.py': '6b4252dc46a78ee085713c1fe732a7e9d49ab6a2f36caf2654b68c616dae5f4c', 'prepare_r2.py': '9223aec1aae8d5d14e59d3888c81fe47dcf9a66eb69fc4df7cd8e2261faa22a2', 'launch_r2.py': '52ce9dda434305a3e32bf791921e19376490590250bde392c50d13781af142b8', 'verify_r2.py': 'c07b19e936a1bcd05233409fd2ebbb4ae76a93657f45117698d8e67fcbcf734d'}
assert {n:hashlib.sha256(v).hexdigest() for n,v in raws.items()}==expected
for n,v in raws.items():compile(v,n,'exec')
contract=types.ModuleType('r2_contract');sys.modules[contract.__name__]=contract
exec(compile(raws['r2_contract.py'],'r2_contract.py','exec'),contract.__dict__)
guards=types.ModuleType('r2_guards_inmemory');sys.modules[guards.__name__]=guards
guards.SOURCE_RAW_FILES=raws;guards.REFERENCE_RAW_FILES=refs
exec(compile(raws['verify_r2.py'],'verify_r2.py','exec'),guards.__dict__)
suite=unittest.defaultTestLoader.loadTestsFromModule(guards);assert suite.countTestCases()==58
result=unittest.TextTestRunner(verbosity=2).run(suite)
print(json.dumps({'status':'PASS' if result.wasSuccessful() else 'FAILED','pythonVersion':sys.version,'guardTestCount':result.testsRun,'sourceSha256':expected,'compiledSourceCount':len(raws),'remoteSourceFilesWritten':0,'realDockerCalls':0,'cacheOperations':0,'productionConnections':0}))
assert result.wasSuccessful()
